static const float HILLS[24] = { 844.18, 677.27, 1.00, 158.05, 406.33, 1278.21, 0.48, 102.12, 107.69, 618.01, 0.66, 224.45, 822.21, 981.87, 0.46, 183.13, 301.69, 469.41, 0.57, 227.77, 977.14, 1124.87, 0.65, 216.59 };
float4 shade(float2 pos, float px) {
    float h = 0.0;
    float2 g = float2(0.0, 0.0);
    for (int i = 0; i < 6; i++) {
        float2 d = pos - float2(HILLS[i * 4], HILLS[i * 4 + 1]);
        float s = HILLS[i * 4 + 3];
        float e = HILLS[i * 4 + 2] * exp(-dot(d, d) / (2.0 * s * s));
        h += e;
        g += -e * d / (s * s);
    }
    float iv = 0.05;
    float k = h / iv;
    float dist = abs(frac(k + 0.5) - 0.5) * iv / max(length(g), 1e-5);
    float major = step(abs(fmod(round(k), 4.0)), 0.5);
    float line = saturate(lerp(0.65, 1.3, major) + 0.5 - dist / px) * smoothstep(0.015, 0.04, h);
    float a = line * lerp(0.130, 0.280, major);
    return float4(float3(0.0242, 0.008, 0.0018) * a, a);
}
